"use client"
import * as React from "react"
import { animate, motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring, useTransform, type MotionValue } from "framer-motion"
import { ChevronLeft, ChevronRight, LayoutGrid, Moon, Ruler, Sun } from "lucide-react"
import { cn } from "@/lib/utils"

type Kind = "dashboard" | "inbox" | "calendar" | "editor" | "insights"
export interface LensShot {
  id: string
  title: string
  blurb: string
  tag: string
  /** Which built-in screen sketch to draw. Pass `screen` instead to render your own image. */
  kind?: Kind
  /** Optional custom screenshot. It is shown as the polished layer; the blueprint layer is still drawn from `kind`. */
  screen?: string
}
export interface LensReelProps {
  items: LensShot[]
  title?: string
  defaultIndex?: number
  /** "system" follows prefers-color-scheme until the user presses the toggle. */
  theme?: "system" | "light" | "dark"
  onChange?: (index: number) => void
  className?: string
}

type R = [number, number, number, number, "p" | "b" | "t" | "c" | "a" | "o"]
const W = 300, H = 190
const rows = (n: number, f: (i: number) => R[]) => Array.from({ length: n }, (_, i) => f(i)).flat()
const SKETCH: Record<Kind, R[]> = {
  dashboard: [[0, 0, 52, 190, "p"], [64, 12, 120, 10, "t"], [236, 10, 52, 16, "c"], [64, 36, 70, 44, "p"], [142, 36, 70, 44, "p"], [220, 36, 68, 44, "a"],
    [70, 128, 14, 50, "b"], [92, 112, 14, 66, "b"], [114, 132, 14, 46, "b"], [136, 100, 14, 78, "b"], [158, 120, 14, 58, "b"], [180, 94, 14, 84, "b"],
    [210, 92, 78, 86, "p"], [220, 104, 50, 6, "t"], [220, 118, 38, 6, "t"], [220, 132, 56, 6, "t"], [10, 14, 32, 8, "t"], [10, 34, 32, 6, "t"], [10, 48, 32, 6, "t"], [10, 62, 32, 6, "t"]],
  inbox: rows(5, (i) => [[16, 14 + i * 34, 268, 28, "p"], [26, 24 + i * 34, 8, 8, "c"], [44, 21 + i * 34, 110, 6, "t"], [44, 32 + i * 34, 170, 5, "t"], ...(i % 2 === 0 ? ([[244, 22 + i * 34, 30, 10, "a"]] as R[]) : [])]),
  calendar: [[16, 10, 100, 12, "t"], [236, 8, 48, 16, "c"], ...rows(28, (i) => [[16 + (i % 7) * 38, 36 + Math.floor(i / 7) * 35, 34, 30, "p"]]), [92, 71, 34, 30, "a"], [130, 106, 72, 30, "c"], [206, 141, 34, 30, "a"]],
  editor: [[16, 10, 268, 20, "p"], [28, 44, 150, 14, "t"], [28, 70, 150, 6, "t"], [28, 84, 132, 6, "t"], [28, 98, 160, 6, "t"], [28, 112, 110, 6, "t"], [196, 64, 80, 74, "a"], [28, 150, 66, 24, "c"], [104, 150, 66, 24, "p"], [200, 150, 76, 6, "t"]],
  insights: [[16, 14, 120, 12, "t"], [16, 40, 120, 130, "p"], [76, 105, 44, 44, "o"], [150, 40, 134, 36, "p"], [150, 84, 134, 36, "p"], [150, 128, 134, 42, "p"], [160, 52, 60, 6, "t"], [160, 96, 80, 6, "t"], [160, 140, 50, 6, "t"], [236, 134, 40, 24, "b"]],
}

function Sketch({ kind, wire, img }: { kind: Kind; wire: boolean; img?: string }) {
  const rects = SKETCH[kind]
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="absolute inset-0 size-full" aria-hidden preserveAspectRatio="none">
      <rect width={W} height={H} style={{ fill: wire ? "var(--card)" : "var(--muted)" }} />
      {!wire && img && <image href={img} width={W} height={H} preserveAspectRatio="xMidYMid slice" />}
      {wire && <>
        <defs><pattern id={`g-${kind}`} width="10" height="10" patternUnits="userSpaceOnUse"><path d="M10 0H0V10" fill="none" style={{ stroke: "var(--primary)", opacity: 0.16 }} strokeWidth="0.5" /></pattern></defs>
        <rect width={W} height={H} fill={`url(#g-${kind})`} />
      </>}
      {!(img && !wire) && rects.map(([x, y, w, h, t], i) => {
        if (wire) {
          return (
            <g key={i}>
              {t === "o" ? <circle cx={x} cy={y} r={w} fill="none" strokeDasharray="3 2" strokeWidth="0.8" style={{ stroke: "var(--primary)" }} /> : <rect x={x} y={y} width={w} height={h} rx={t === "t" ? 1 : 3} fill="none" strokeDasharray="3 2" strokeWidth="0.8" style={{ stroke: "var(--primary)" }} />}
              {w >= 26 && h >= 9 && t !== "o" && <text x={x + 3} y={y + 8} fontSize="6" fontFamily="ui-monospace,monospace" style={{ fill: "var(--primary)" }}>{w}x{h}</text>}
              {t === "o" && <text x={x - 10} y={y + 2} fontSize="6" fontFamily="ui-monospace,monospace" style={{ fill: "var(--primary)" }}>r{w}</text>}
            </g>
          )
        }
        if (t === "o") return <g key={i}><circle cx={x} cy={y} r={w} fill="none" strokeWidth="14" style={{ stroke: "var(--border)" }} /><circle cx={x} cy={y} r={w} fill="none" strokeWidth="14" strokeDasharray="170 400" transform={`rotate(-90 ${x} ${y})`} style={{ stroke: "var(--primary)" }} /></g>
        const fill = t === "p" ? "var(--card)" : t === "b" ? "var(--primary)" : t === "t" ? "var(--muted-foreground)" : t === "c" ? "var(--primary)" : "color-mix(in oklab,var(--primary) 22%,var(--card))"
        return <rect key={i} x={x} y={y} width={w} height={h} rx={t === "t" ? 3 : t === "b" ? 2 : 6} style={{ fill, opacity: t === "t" ? 0.4 : 1, stroke: t === "p" ? "var(--border)" : "none" }} strokeWidth="1" />
      })}
    </svg>
  )
}

function Slide({ item, i, pos, w, reduce, active, full }: { item: LensShot; i: number; pos: MotionValue<number>; w: number; reduce: boolean; active: boolean; full: boolean }) {
  const d = useTransform(pos, (p) => i - p)
  const x = useTransform(d, (v) => (reduce ? v * (w + 16) : Math.sign(v) * Math.min(Math.abs(v), 1) * w * 0.66 + Math.max(0, Math.abs(v) - 1) * w * 0.22 * Math.sign(v)))
  const rotateY = useTransform(d, (v) => (reduce ? 0 : Math.max(-1.3, Math.min(1.3, v)) * -42))
  const scale = useTransform(d, (v) => (reduce ? 1 : 1 - Math.min(Math.abs(v), 2) * 0.13))
  const z = useTransform(d, (v) => (reduce ? 0 : -Math.min(Math.abs(v), 2) * 140))
  const opacity = useTransform(d, (v) => Math.max(0, 1 - Math.abs(v) * (reduce ? 1 : 0.4)))
  const zi = useTransform(d, (v) => 100 - Math.round(Math.abs(v) * 10))
  const lx = useSpring(useMotionValue(w / 2), { stiffness: 380, damping: 32 })
  const ly = useSpring(useMotionValue(70), { stiffness: 380, damping: 32 })
  const lr = useMotionValue(0)
  const mag = useMotionValue(1.2)
  const h = (w * H) / W
  React.useEffect(() => { if (full) { lx.set(w / 2); ly.set(h / 2) } animate(lr, full ? Math.hypot(w, h) / 2 + 12 : 0, { type: "spring", stiffness: 160, damping: 22 }); animate(mag, full ? 1 : 1.2, { duration: 0.4 }) }, [full, lr, mag, w, h, lx, ly])
  const clip = useMotionTemplate`circle(${lr}px at ${lx}px ${ly}px)`
  const origin = useMotionTemplate`${lx}px ${ly}px`
  const ringX = useTransform([lx, lr] as MotionValue<number>[], ([a, r]: number[]) => a - r)
  const ringY = useTransform([ly, lr] as MotionValue<number>[], ([a, r]: number[]) => a - r)
  const ringS = useTransform(lr, (r) => r * 2)
  const ringO = useTransform(lr, (r) => (r > w * 0.9 || r < 4 ? 0 : 1))
  const move = (e: React.PointerEvent) => {
    if (!active || full || reduce || e.pointerType !== "mouse" || e.buttons) return
    const b = e.currentTarget.getBoundingClientRect()
    lx.set(e.clientX - b.left); ly.set(e.clientY - b.top)
    if (lr.get() < 50) animate(lr, 58, { type: "spring", stiffness: 300, damping: 18 })
  }
  const leave = () => { if (!full) animate(lr, 0, { duration: 0.25 }) }
  return (
    <motion.li aria-hidden={!active} aria-roledescription="slide" aria-label={item.title} className="absolute left-1/2 top-3 list-none" style={{ width: w, marginLeft: -w / 2, x, rotateY, scale, z, opacity, zIndex: zi, transformStyle: "preserve-3d" }}>
      <div onPointerMove={move} onPointerLeave={leave} onPointerDown={() => animate(lr, full ? lr.get() : 0, { duration: 0.15 })}
        className={cn("relative overflow-hidden rounded-2xl border border-border bg-card shadow-[0_28px_50px_-26px_color-mix(in_oklab,var(--primary)_70%,transparent)]", active && !full && "cursor-none")} style={{ height: h }}>
        <Sketch kind={item.kind ?? "dashboard"} wire={false} img={item.screen} />
        <motion.div aria-hidden className="pointer-events-none absolute inset-0" style={{ clipPath: clip, WebkitClipPath: clip }}>
          <motion.div className="absolute inset-0" style={{ scale: mag, transformOrigin: origin }}><Sketch kind={item.kind ?? "dashboard"} wire /></motion.div>
        </motion.div>
        <motion.div aria-hidden className="pointer-events-none absolute left-0 top-0 rounded-full border-2 border-primary" style={{ x: ringX, y: ringY, width: ringS, height: ringS, opacity: ringO, boxShadow: "0 0 24px 2px color-mix(in oklab,var(--primary) 55%,transparent), inset 0 0 14px color-mix(in oklab,var(--primary) 35%,transparent)" }} />
      </div>
    </motion.li>
  )
}

function useDark(theme: "system" | "light" | "dark") {
  const [dark, setDark] = React.useState(theme === "dark")
  React.useEffect(() => {
    if (theme !== "system") { setDark(theme === "dark"); return }
    const m = window.matchMedia("(prefers-color-scheme: dark)"); setDark(m.matches)
    const f = (e: MediaQueryListEvent) => setDark(e.matches); m.addEventListener("change", f); return () => m.removeEventListener("change", f)
  }, [theme])
  return [dark, setDark] as const
}

export function LensReel({ items, title = "Product tour", defaultIndex = 0, theme = "system", onChange, className }: LensReelProps) {
  const reduce = !!useReducedMotion()
  const [dark, setDark] = useDark(theme)
  const wrap = React.useRef<HTMLDivElement>(null)
  const [w, setW] = React.useState(300)
  const [index, setIndex] = React.useState(defaultIndex)
  const [full, setFull] = React.useState(false)
  const [overview, setOverview] = React.useState(false)
  const overviewRef = React.useRef<HTMLDivElement>(null)
  const overviewBtnRef = React.useRef<HTMLButtonElement>(null)
  const pos = useMotionValue(defaultIndex)
  const [grabbing, setGrabbing] = React.useState(false)
  const down = React.useRef<{ x: number; p: number; t: number; v: number; moved: number } | null>(null)
  React.useEffect(() => { if (overview) overviewRef.current?.focus() }, [overview])
  const closeOverview = React.useCallback(() => { setOverview(false); overviewBtnRef.current?.focus() }, [])
  React.useEffect(() => {
    const el = wrap.current; if (!el) return
    const f = () => setW(Math.min(320, el.offsetWidth - 48)); const ro = new ResizeObserver(f); ro.observe(el); f(); return () => ro.disconnect()
  }, [])
  const goTo = React.useCallback((n: number, velocity = 0) => {
    const t = Math.max(0, Math.min(items.length - 1, n)); setIndex(t); onChange?.(t)
    animate(pos, t, reduce ? { duration: 0.2 } : { type: "spring", stiffness: 150, damping: 18, velocity })
  }, [items.length, onChange, pos, reduce])
  const onDown = (e: React.PointerEvent) => { if (reduce) return; (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); pos.stop(); down.current = { x: e.clientX, p: pos.get(), t: performance.now(), v: 0, moved: 0 }; setGrabbing(true) }
  const onMove = (e: React.PointerEvent) => {
    const d = down.current; if (!d) return
    const next = d.p - (e.clientX - d.x) / (w * 0.66), now = performance.now()
    d.v = (d.p - next - (d.p - pos.get())) / Math.max(1, now - d.t) * 1000; d.t = now
    pos.set(Math.max(-0.4, Math.min(items.length - 0.6, next)))
  }
  const onUp = () => { const d = down.current; down.current = null; setGrabbing(false); if (d) goTo(Math.round(pos.get() - d.v * 0.12), -d.v) }
  const key = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowRight") { e.preventDefault(); goTo(index + 1) } else if (e.key === "ArrowLeft") { e.preventDefault(); goTo(index - 1) }
    else if (e.key === "Home") { e.preventDefault(); goTo(0) } else if (e.key === "End") { e.preventDefault(); goTo(items.length - 1) }
    else if (e.key.toLowerCase() === "b") setFull((v) => !v)
  }
  const glow = useMotionTemplate`radial-gradient(55% 60% at ${useTransform(pos, [0, Math.max(1, items.length - 1)], ["15%", "85%"])} 30%, color-mix(in oklab, var(--primary) 24%, transparent), transparent)`
  const cur = items[index]
  const btn = "grid size-11 shrink-0 place-items-center rounded-full border border-border bg-card outline-none transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:opacity-35"
  return (
    <div data-theme="neon" className={cn(dark && "dark", "w-full max-w-xl")}>
      <section aria-roledescription="carousel" aria-label={title} className={cn("relative w-full overflow-hidden rounded-3xl border border-border bg-background p-5 pb-6 text-foreground", className)}>
        <motion.div aria-hidden className="pointer-events-none absolute inset-0" style={{ background: glow }} />
        <div className="relative flex items-center justify-between gap-2">
          <h2 className="text-lg font-semibold tracking-tight">{title}</h2>
          <div className="flex gap-1.5">
            <button ref={overviewBtnRef} type="button" aria-pressed={overview} onClick={() => setOverview((v) => !v)} className={cn(btn, "flex w-auto items-center justify-center gap-1.5 px-3.5 text-sm font-medium", overview && "border-primary bg-primary text-primary-foreground hover:bg-primary")}>
              <LayoutGrid className="size-4" aria-hidden /><span>Overview</span>
            </button>
            <button type="button" aria-pressed={full} onClick={() => setFull((v) => !v)} className={cn(btn, "flex w-auto items-center justify-center gap-1.5 px-3.5 text-sm font-medium", full && "border-primary bg-primary text-primary-foreground hover:bg-primary")}>
              <Ruler className="size-4" aria-hidden /><span>Blueprint</span>
            </button>
            <button type="button" aria-pressed={dark} aria-label="Dark theme" onClick={() => setDark((v) => !v)} className={btn}>
              {dark ? <Sun className="size-4" aria-hidden /> : <Moon className="size-4" aria-hidden />}
            </button>
          </div>
        </div>
        <div className="relative">
          <div className={cn(overview && "invisible")}>
            <div ref={wrap} tabIndex={0} role="group" aria-label="Product screens. Use the arrow keys or drag. Press B for the blueprint view." onKeyDown={key} onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}
              className={cn("relative mt-3 touch-pan-y select-none rounded-2xl outline-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", grabbing ? "cursor-grabbing" : "cursor-grab")} style={{ perspective: 1000, height: (w * H) / W + 28 }}>
              <ul className="relative h-full" style={{ transformStyle: "preserve-3d" }}>
                {items.map((it, i) => <Slide key={it.id} item={it} i={i} pos={pos} w={w} reduce={reduce} active={i === index} full={full} />)}
              </ul>
            </div>
            <div className="relative mt-2 flex items-center gap-3">
              <button type="button" className={btn} aria-label="Previous screen" disabled={index === 0} onClick={() => goTo(index - 1)}><ChevronLeft className="size-4" aria-hidden /></button>
              <div className="min-w-0 flex-1 text-center" aria-live="polite">
                <p className="flex items-center justify-center gap-2 text-sm font-semibold"><span>{cur.title}</span><span className="rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground">{cur.tag}</span></p>
                <p className="mt-0.5 truncate text-sm text-muted-foreground">{cur.blurb}</p>
              </div>
              <button type="button" className={btn} aria-label="Next screen" disabled={index === items.length - 1} onClick={() => goTo(index + 1)}><ChevronRight className="size-4" aria-hidden /></button>
            </div>
            <div className="relative mt-2 flex justify-center">
              {items.map((it, i) => (
                <button key={it.id} type="button" aria-label={`Show screen ${i + 1} of ${items.length}`} aria-current={i === index} onClick={() => goTo(i)} className="grid size-7 place-items-center outline-none focus-visible:outline-2 focus-visible:outline-ring">
                  <motion.span className="block rounded-full" animate={{ width: i === index ? 18 : 6, background: i === index ? "var(--primary)" : "var(--border)" }} style={{ height: 6 }} transition={{ type: "spring", stiffness: 400, damping: 22 }} />
                </button>
              ))}
            </div>
            <p className="relative mt-1 text-center text-xs text-muted-foreground">Hover a screen to peek at its blueprint</p>
          </div>
          {overview && (
            <div ref={overviewRef} tabIndex={-1} role="group" aria-label={`Overview of ${items.length} screens. Choose one to jump to it, or press Escape to go back.`} onKeyDown={(e) => { if (e.key === "Escape") { e.preventDefault(); closeOverview() } }}
              className="absolute inset-0 z-20 overflow-y-auto rounded-2xl border border-border bg-background p-2 outline-none">
              <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-3">
                {items.map((it, i) => (
                  <button key={it.id} type="button" onClick={() => { goTo(i); closeOverview() }} aria-current={i === index}
                    className={cn("overflow-hidden rounded-xl border text-left outline-none transition focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring", i === index ? "border-primary ring-2 ring-primary/30" : "border-border hover:border-primary/60")}>
                    <div className="relative aspect-[300/190] w-full overflow-hidden"><Sketch kind={it.kind ?? "dashboard"} wire={false} img={it.screen} /></div>
                    <div className="flex items-center justify-between gap-2 border-t border-border bg-card px-2.5 py-1.5">
                      <span className="truncate text-xs font-medium">{it.title}</span>
                      <span className="shrink-0 rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">{i + 1}/{items.length}</span>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </section>
    </div>
  )
}
